def _backfill_partner_totals() -> None:
    """Fill KNC1/LFC1 from the customer/vendor items posted before this revision."""
    bind = op.get_bind()
    bkpf = sa.table("bkpf", sa.column("mandt"), sa.column("bukrs"), sa.column("belnr"), sa.column("gjahr"),
                    sa.column("monat"), sa.column("bstat"))
    bseg = sa.table("bseg", sa.column("mandt"), sa.column("bukrs"), sa.column("belnr"), sa.column("gjahr"),
                    sa.column("koart"), sa.column("kunnr"), sa.column("lifnr"), sa.column("shkzg"), sa.column("dmbtr"))
    rows = bind.execute(sa.select(
        bseg.c.mandt, bseg.c.bukrs, bseg.c.gjahr, bkpf.c.monat, bseg.c.koart, bseg.c.kunnr, bseg.c.lifnr,
        bseg.c.shkzg, sa.func.sum(bseg.c.dmbtr),
    ).select_from(bseg.join(bkpf, sa.and_(
        bseg.c.mandt == bkpf.c.mandt, bseg.c.bukrs == bkpf.c.bukrs,
        bseg.c.belnr == bkpf.c.belnr, bseg.c.gjahr == bkpf.c.gjahr,
    ))).where(bkpf.c.bstat == " ", bseg.c.koart.in_(["D", "K"])).group_by(
        bseg.c.mandt, bseg.c.bukrs, bseg.c.gjahr, bkpf.c.monat, bseg.c.koart, bseg.c.kunnr, bseg.c.lifnr,
        bseg.c.shkzg)).all()
    totals: dict = {}
    for mandt, bukrs, gjahr, monat, koart, kunnr, lifnr, shkzg, amount in rows:
        key = (koart, mandt, kunnr if koart == "D" else lifnr, bukrs, gjahr)
        rec = totals.setdefault(key, {})
        col = f"um{int(monat):02d}{'s' if shkzg == 'S' else 'h'}"
        rec[col] = rec.get(col, 0) + amount
    periods = [f"um{p:02d}{side}" for side in "sh" for p in range(1, 17)]
    # Years that received a balance carryforward (GLT0-HSLVT) start from the partner's earlier movements.
    glt0 = sa.table("glt0", sa.column("mandt"), sa.column("bukrs"), sa.column("gjahr"), sa.column("hslvt"))
    carried = {(m, b, int(y)) for m, b, y in bind.execute(
        sa.select(glt0.c.mandt, glt0.c.bukrs, glt0.c.gjahr).where(glt0.c.hslvt != 0).distinct())}
    movement = {key: sum(v.get(f"um{p:02d}s", 0) - v.get(f"um{p:02d}h", 0) for p in range(1, 17))
                for key, v in totals.items()}
    for koart, mandt, partner, bukrs in {k[:4] for k in totals}:
        for (m, b, year) in sorted(carried):
            if (m, b) != (mandt, bukrs):
                continue
            umsav = sum(mv for (ko, mm, pa, bk, y), mv in movement.items()
                        if (ko, mm, pa, bk) == (koart, mandt, partner, bukrs) and y < year)
            if umsav:
                totals.setdefault((koart, mandt, partner, bukrs, year), {})["umsav"] = umsav
    for (koart, mandt, partner, bukrs, gjahr), values in totals.items():
        table, key = ("knc1", "kunnr") if koart == "D" else ("lfc1", "lifnr")
        cols = ["mandt", key, "bukrs", "gjahr", "umsav", *periods]
        t = sa.table(table, *(sa.column(c) for c in cols))
        bind.execute(t.insert().values(mandt=mandt, bukrs=bukrs, gjahr=gjahr, umsav=values.get("umsav", 0),
                                       **{key: partner}, **{c: values.get(c, 0) for c in periods}))


